'use client';import{useEffect,useMemo,useState}from'react';import{Check,Copy,Heart,Share2}from'lucide-react';import type{PromptItem}from'@/lib/prompts';
export default function PromptCustomizer({p}:{p:PromptItem}){const[values,setValues]=useState<Record<string,string>>({}),[copied,setCopied]=useState(false),[favorite,setFavorite]=useState(false);const fields=useMemo(()=>[...p.prompt.matchAll(/\[([^\]]+)\]/g)].map(x=>x[1]).filter((x,i,a)=>a.indexOf(x)===i),[p.prompt]);const final=fields.reduce((s,f)=>s.replaceAll('['+f+']',values[f]||'['+f+']'),p.prompt);useEffect(()=>{const favs=JSON.parse(localStorage.getItem('ps-favorites')||'[]');setFavorite(favs.includes(p.id));const r:string[]=JSON.parse(localStorage.getItem('ps-recent')||'[]');localStorage.setItem('ps-recent',JSON.stringify([p.id,...r.filter(x=>x!==p.id)].slice(0,8)))},[p.id]);const save=()=>{let f:string[]=JSON.parse(localStorage.getItem('ps-favorites')||'[]');f=f.includes(p.id)?f.filter(x=>x!==p.id):[...f,p.id];localStorage.setItem('ps-favorites',JSON.stringify(f));setFavorite(f.includes(p.id))};const copy=async()=>{await navigator.clipboard.writeText(final);setCopied(true);setTimeout(()=>setCopied(false),1200)};const share=async()=>navigator.share?navigator.share({title:p.title,text:p.summary,url:location.href}):navigator.clipboard.writeText(location.href);return <><div className="detailActions"><button className={favorite?'saved':''} onClick={save}><Heart size={17} fill={favorite?'currentColor':'none'}/>{favorite?'Saved':'Save prompt'}</button><button onClick={share}><Share2 size={17}/>Share</button></div><div className="fields">{fields.map(f=><label key={f}>{f}<input value={values[f]||''} onChange={e=>setValues({...values,[f]:e.target.value})} placeholder={'Enter '+f.toLowerCase()}/></label>)}</div><div className="promptText"><small>YOUR CUSTOMIZED PROMPT</small><p>{final}</p><button onClick={copy}>{copied?<Check/>:<Copy/>}{copied?'Copied':'Copy prompt'}</button></div></>}
